Ext.define('BNK.view.HumanResource.hwm.HwmWplAply01MViewController', {
    extend: 'BaseViewController',
    alias: 'controller.HwmWplAply01MViewController',

    config: {
        viewId: 'HwmWplAply01M'
    },

    defaut: function() {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            store = vm.storeInfo.WplStore;

        store.getProxy().extraParams.page = 1;
        var toolbar = refs.grid.getPlugins()[0];
        toolbar.setCurrentPage(1);
    },

    onBtnSearch: function(button, e, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            params = params || {},
            store = vm.storeInfo.WplStore;

        params.hrHrpmEmpId = SecurityUtils.getPrincipal().hrHrpmEmpId;




        var dateCompont = ['strdt',
            'edt'
            ];

        if(refs[dateCompont[0]].getValue() > refs[dateCompont[1]].getValue()){
            Ext.Msg.alert('확인','시작일이 종료일보다 클 수 없습니다.');
            return;

        }

        for(var key in dateCompont ){
            var dateObj = refs[dateCompont[key]];
            var date = dateObj.getValue();
            var tempMonth = date.getMonth()+1 ;
            var tempDate = date.getDate();
            tempMonth += "";
            tempMonth = (tempMonth.length == 1 ? "0" :"") + tempMonth;
            tempDate += "";
            tempDate = (tempDate.length == 1 ? "0" :"") + tempDate;
            params[dateCompont[key]] = date.getFullYear() +"" + tempMonth + ""+tempDate;
        }


        if(params =={}){
        store.getProxy().extraParams.page = 1;
        var toolbar = refs.grid.getPlugins()[0];
        toolbar.setCurrentPage(1);

    }else{
        store.getProxy().extraParams = params;

    }

    store.removeAll();
    store.load();
    },

    /* 근무지변경 신청 버튼 탭 이벤트 : 상세 신청 페이지로 이동 */
    onBtnWrite: function(button, e, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences();

        var naviView = me.getView().up('navigationview');
        me.PUSH_VIEW(naviView, {
            menuId  : 'HwmWplAply02M',
            title   : '근무지변경 신청',
            parentView : me.getView(),
            isSubView : true,
            records : []
        });

    },

    /* row 탭으로 신청한 근무지변경 내역 보기 */
    onGridSelect: function(dataview, selected, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            record = selected[0].data; // 선택한 row 들


            if (!(record.comAprHistId)) {
                Ext.Msg.alert('확인', Messages.getMessage('E9303', [ '신청서' ]));
            return;
        } else {
            // 결재이력조회
            Ext.Ajax.request({
                headers : {
                    serviceId : 'COMAPR0001R04',
                    viewId : 'HwmWplAply01M'
                },
                scope : me,
                jsonData : {
                    aprHistId : record.comAprHistId	// 결재이력ID
                },
                success : function(response, scope) {
                    //                     var me = scope,
                    var command = Constants.sanction.COMPLETED_BOX, // 아무 동작도 하지 않아야 하므로 완료.
                    responseText = JSON.parse(response.responseText),
                    responseJson = Ext.JSON.decode(Ext.JSON.decode(response.responseText).result);

                    vm.set('responseJson', responseJson);


                    var win = Ext.create('HwmWplAply71M', {
                        viewId : me.getView().xtype,
                        command : responseText.command,
                        aprHistId : responseJson.aprHistId,
                        aprHistData : responseJson,
                        docData : responseJson.docData,
                        record : record
                    });

                    // 재조회
                    me.mon(win, 'complete', function(view) {
                        me.onSelect(); // 재조회
                    }, me);
                    win.show();
                }
            });
        }
    },

    /* 화면초기화 */
    initialize: function(component, eOpts) {
        var me = this,
            refs = me.getReferences(),
            grid = refs.grid;

        var dateMinus1 = new Date();
        dateMinus1.setDate(1);
        refs.strdt.setValue(DateUtils.parseDate(dateMinus1));

        dateMinus1.setMonth(dateMinus1.getMonth()+1);
        dateMinus1.setDate(7);
        refs.edt.setValue(DateUtils.parseDate(dateMinus1));

        grid.el.select('.x-headercontainer').setStyle('height',	'0px');
        this.onBtnSearch();
    },

    /* 페이징 등 스토어가 새로 load 될때 동작하는 이벤트 */
    onJsonstoreLoad: function(store, records, successful, operation, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            grid = refs.grid;

    }

});